"use client"

import * as React from "react"
import {
  createColumnHelper,
  createSortedRowModel,
  rowSelectionFeature,
  rowSortingFeature,
  tableFeatures,
} from "@tanstack/react-table"
import { cn } from "cn"
import {
  CopyIcon,
  MoreVerticalIcon,
  PencilIcon,
  ShareIcon,
  TrashIcon,
} from "lucide-react"

import { Badge } from "@tecton/react/components/badge"
import { Button } from "@tecton/react/components/button"
import { Checkbox } from "@tecton/react/components/checkbox"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@tecton/react/components/dropdown-menu"
import { Meter } from "@tecton/react/tecton/meter"
import { useLocale } from "@tecton/react/tecton/provider"

import { formatFirstOil, riskLabel, statusMeta } from "../data"
import type { FieldDevelopmentAlternative } from "../data"

// TanStack Table v9: the features the FDA comparison table uses.
const fdaTableFeatures = tableFeatures({
  rowSelectionFeature,
  rowSortingFeature,
  sortedRowModel: createSortedRowModel(),
})

const columns = createColumnHelper<
  typeof fdaTableFeatures,
  FieldDevelopmentAlternative
>()

function MonoValue({
  value,
  unit,
  className,
  digits = 1,
  prefix,
}: {
  value: number
  unit?: string
  className?: string
  digits?: number
  prefix?: string
}) {
  const { locale } = useLocale()
  return (
    <span className={cn("font-mono tabular-nums", className)}>
      {prefix}
      {value.toLocaleString(locale, {
        minimumFractionDigits: digits,
        maximumFractionDigits: digits,
      })}
      {unit && (
        <span className="ms-1 text-[0.85em] text-muted-foreground">{unit}</span>
      )}
    </span>
  )
}

type ColumnCallbacks = {
  onOpen?: ((fda: FieldDevelopmentAlternative) => void) | undefined
  onDuplicate?: (fda: FieldDevelopmentAlternative) => void
  onDelete?: (fda: FieldDevelopmentAlternative) => void
}

/** Column definitions for the FDA comparison table. */
function createFdaColumns(callbacks: ColumnCallbacks = {}) {
  return columns.columns([
    columns.display({
      id: "select",
      header: ({ table }) => {
        // Checked when every row is selected, mixed when some are.
        const rows = table.getRowModel().rows
        const all = rows.length > 0 && rows.every((row) => row.getIsSelected())
        const some = table.getSelectedRowModel().rows.length > 0
        return (
          <Checkbox
            aria-label="Select all rows"
            checked={all}
            indeterminate={some && !all}
            onCheckedChange={(checked) => {
              if (checked) table.toggleAllRowsSelected(true)
              else table.setRowSelection({})
            }}
          />
        )
      },
      cell: ({ row }) => (
        <Checkbox
          aria-label={`Select row ${row.original.code}`}
          checked={row.getIsSelected()}
          onCheckedChange={(checked) => row.toggleSelected(checked)}
        />
      ),
      enableSorting: false,
    }),
    columns.display({
      id: "rank",
      header: "Rank",
      cell: ({ row }) => (
        <span className="flex items-center gap-2">
          <span
            aria-hidden
            className="h-6 w-1.5 shrink-0 rounded-sm"
            style={{ background: row.original.color }}
          />
          <span className="font-mono tabular-nums">{row.index + 1}</span>
        </span>
      ),
    }),
    columns.accessor("code", {
      header: "FDA",
      cell: ({ row, getValue }) => (
        <span className="flex min-w-0 items-center gap-2">
          <span className="shrink-0 font-mono text-muted-foreground">
            {getValue()}
          </span>
          <span className="truncate font-medium">{row.original.name}</span>
        </span>
      ),
    }),
    columns.accessor("npv", {
      header: "NPV",
      cell: ({ getValue }) => (
        <MonoValue
          value={getValue()}
          prefix="$"
          unit="MM"
          className="text-success"
        />
      ),
    }),
    columns.accessor("irr", {
      header: "IRR",
      cell: ({ getValue }) => <MonoValue value={getValue()} unit="%" />,
    }),
    columns.accessor("capex", {
      header: "CAPEX",
      cell: ({ getValue }) => (
        <MonoValue value={getValue()} prefix="$" unit="MM" />
      ),
    }),
    columns.accessor("peakProduction", {
      header: "Peak production",
      cell: ({ getValue }) => <MonoValue value={getValue()} unit="Mbbl/d" />,
    }),
    columns.accessor("firstOil", {
      header: "First oil",
      cell: ({ getValue }) => (
        <span className="font-mono tabular-nums">
          {formatFirstOil(getValue())}
        </span>
      ),
    }),
    columns.accessor("risk", {
      header: "Risk",
      cell: ({ getValue }) => (
        <Meter
          aria-label={`Risk ${riskLabel(getValue())}`}
          value={getValue()}
          color="auto"
          size="sm"
          segments={5}
          valueLabel={
            <span className="text-[0.625rem]">{riskLabel(getValue())}</span>
          }
          className="w-28 gap-0.5"
        />
      ),
    }),
    columns.accessor("status", {
      header: "Status",
      cell: ({ getValue }) => {
        const meta = statusMeta[getValue()]
        return (
          <Badge
            variant={meta.color}
            appearance={getValue() === "archived" ? "outline" : "solid"}
          >
            {meta.label}
          </Badge>
        )
      },
    }),
    columns.display({
      id: "actions",
      header: "",
      enableSorting: false,
      cell: ({ row }) => (
        <span className="flex justify-end">
          <DropdownMenu>
            <DropdownMenuTrigger
              render={
                <Button
                  variant="ghost"
                  size="icon-xs"
                  aria-label={`Actions for ${row.original.code}`}
                />
              }
            >
              <MoreVerticalIcon />
            </DropdownMenuTrigger>
            <DropdownMenuContent side="bottom" align="end">
              <DropdownMenuItem
                onClick={() => callbacks.onOpen?.(row.original)}
              >
                <PencilIcon /> Open
              </DropdownMenuItem>
              <DropdownMenuItem
                onClick={() => callbacks.onDuplicate?.(row.original)}
              >
                <CopyIcon /> Duplicate
              </DropdownMenuItem>
              <DropdownMenuItem>
                <ShareIcon /> Share
              </DropdownMenuItem>
              <DropdownMenuSeparator />
              <DropdownMenuItem
                variant="destructive"
                onClick={() => callbacks.onDelete?.(row.original)}
              >
                <TrashIcon /> Delete
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </span>
      ),
    }),
  ])
}

export { createFdaColumns, fdaTableFeatures, MonoValue }
export type { ColumnCallbacks }

"use client"

import * as React from "react"
import { useTable } from "@tanstack/react-table"
import type { RowSelectionState, SortingState } from "@tanstack/react-table"
import { cn } from "cn"
import { PlusIcon } from "lucide-react"

import { Button } from "@tecton/react/components/button"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@tecton/react/components/table"

import {
  createFdaColumns,
  fdaTableFeatures,
  MonoValue,
} from "./components/fda-columns"
import { alternatives as allAlternatives } from "./data"
import type { FieldDevelopmentAlternative } from "./data"

type FdaComparisonTableProps = React.ComponentProps<"div"> & {
  data?: FieldDevelopmentAlternative[]
  onOpen?: (fda: FieldDevelopmentAlternative) => void
  onAddComparison?: () => void
}

/**
 * FDA comparison table — ranked field development alternatives with mono
 * economics, an auto-coloured risk meter, status badges and a row menu.
 * TanStack Table state (sorting, selection) rendered with the `Table` parts
 * in a compact, alternating-row layout: a header sorts its column, a row's
 * checkbox selects it, and a click on a row (outside its controls) opens it
 * — the row's actions menu opens it from the keyboard.
 */
function FdaComparisonTable({
  className,
  data = allAlternatives,
  onOpen,
  onAddComparison,
  ...props
}: FdaComparisonTableProps) {
  const [rows, setRows] = React.useState(data)
  const [sorting, setSorting] = React.useState<SortingState>([])
  const [rowSelection, setRowSelection] = React.useState<RowSelectionState>({})
  // Copies are numbered by a counter that only grows, so an id is never
  // reused after a row is deleted (the row count would repeat).
  const copies = React.useRef(0)

  const columns = React.useMemo(
    () =>
      createFdaColumns({
        onOpen,
        onDuplicate: (fda) => {
          copies.current += 1
          const id = `${fda.id}-copy-${copies.current}`
          setRows((current) => [
            ...current,
            {
              ...fda,
              id,
              code: `${fda.code} (copy)`,
              status: "screening",
            },
          ])
        },
        onDelete: (fda) =>
          setRows((current) => current.filter((row) => row.id !== fda.id)),
      }),
    [onOpen]
  )

  const table = useTable({
    features: fdaTableFeatures,
    data: rows,
    columns,
    getRowId: (row) => row.id,
    state: { sorting, rowSelection },
    onSortingChange: setSorting,
    onRowSelectionChange: setRowSelection,
  })

  const selectedCount = table.getSelectedRowModel().rows.length

  return (
    <div
      data-slot="fda-comparison-table"
      className={cn(
        "flex w-full flex-col overflow-hidden rounded-md border bg-card text-xs",
        className
      )}
      {...props}
    >
      <Table aria-label="Field development alternatives">
        <TableHeader className="bg-muted [&_tr]:border-border-subtle">
          <tr>
            {table.getFlatHeaders().map((header) => {
              const sortable = header.column.getCanSort()
              const sorted = header.column.getIsSorted()
              const content = header.isPlaceholder ? null : (
                <table.FlexRender header={header} />
              )
              return (
                <TableHead
                  key={header.id}
                  aria-sort={
                    !sortable
                      ? undefined
                      : sorted === "asc"
                        ? "ascending"
                        : sorted === "desc"
                          ? "descending"
                          : "none"
                  }
                  className={cn(
                    "h-9 px-2 text-xs",
                    header.column.id === "select" && "w-10"
                  )}
                >
                  {sortable ? (
                    // Ascending first, then toggles; one sorted column.
                    <button
                      type="button"
                      className="-mx-1 rounded-sm px-1 outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring"
                      onClick={() =>
                        header.column.toggleSorting(sorted === "asc", false)
                      }
                    >
                      {content}
                    </button>
                  ) : (
                    content
                  )}
                </TableHead>
              )
            })}
          </tr>
        </TableHeader>
        <TableBody className="[&_tr]:border-border-subtle [&_tr:nth-child(even)]:bg-surface-alt/60">
          {table.getRowModel().rows.length === 0 ? (
            <TableRow>
              <TableCell
                colSpan={table.getFlatHeaders().length}
                className="py-8 text-center text-muted-foreground"
              >
                No alternatives yet.
              </TableCell>
            </TableRow>
          ) : (
            table.getRowModel().rows.map((row) => (
              <TableRow
                key={row.id}
                data-selected={row.getIsSelected() ? "" : undefined}
                onClick={(event) => {
                  // Not a click on the row's checkbox or menu, nor one that
                  // reached it through a portal (the menu's popup).
                  const target = event.target as Element
                  if (
                    !onOpen ||
                    !event.currentTarget.contains(target) ||
                    target.closest("button, a, input, [role=checkbox]")
                  )
                    return
                  onOpen(row.original)
                }}
                className={cn(
                  "hover:bg-accent/60 data-[selected]:bg-accent",
                  onOpen && "cursor-pointer"
                )}
              >
                {row.getAllCells().map((cell) => (
                  <TableCell
                    key={cell.id}
                    className={cn(
                      "h-9 px-2",
                      cell.column.id === "select" && "w-10"
                    )}
                  >
                    <table.FlexRender cell={cell} />
                  </TableCell>
                ))}
              </TableRow>
            ))
          )}
        </TableBody>
      </Table>
      <div
        data-slot="fda-comparison-table-footer"
        className="flex items-center justify-between gap-3 border-t bg-muted/60 px-2 py-1.5 text-xs text-muted-foreground"
      >
        <div className="flex items-center gap-2">
          <span className="tabular-nums">
            {selectedCount} of {table.getRowModel().rows.length} selected
          </span>
          <Button
            variant="ghost"
            size="xs"
            {...(onAddComparison === undefined
              ? {}
              : { onClick: onAddComparison })}
          >
            <PlusIcon /> Add comparison
            {selectedCount > 1 && (
              <span className="text-muted-foreground">({selectedCount})</span>
            )}
          </Button>
        </div>
      </div>
    </div>
  )
}

/** Route-ready page: the table with a small summary header. */
export default function FdaComparisonTablePage() {
  return (
    <div
      data-slot="fda-comparison-table-page"
      className="flex min-h-svh w-full flex-col gap-4 bg-background px-4 py-8 text-foreground md:px-8"
    >
      <header className="flex flex-col gap-1">
        <h1 className="text-lg font-medium">Field development alternatives</h1>
        <p className="text-sm text-muted-foreground">
          Ranked by NPV. Select two or more rows to compare cost, schedule and
          risk side by side.
        </p>
      </header>
      <FdaComparisonTable />
    </div>
  )
}

export { FdaComparisonTable, createFdaColumns, MonoValue }
export { alternatives, statusMeta, riskLabel, formatFirstOil } from "./data"
export type { FdaComparisonTableProps }
export type { FieldDevelopmentAlternative, FdaStatus } from "./data"
